mu[3] <- exp(c+e[3] + D1*e[2] + D2*e[1]);

for (i in 4:N) {

mu[i] <- exp(c+e[i] + D1*e[i-1] + D2*e[i-2]+D3*e[i-3]);
}

}

model {
u ~ uniform(-1,1);
c ~ normal(0,10);
d ~ uniform(0,0.5);
