#before I pass it to stan I have to format and subtract off the last entry
numbers<-as.integer(unlist(cumsum(countrycounts$n)))+1
numbers[length(numbers)]<-numbers[length(numbers)]-1

#I pass this to my stan model in Rstan, and also pass J as an interger indicating the number of countries
