this seems to work:

lower boundary responses should no longer be coded as negative response times; instead the response times and responses should be passed to stan as data:

library(rstan)
library(RWiener)

set.seed(0)
dat <- rwiener(n = 5000, alpha = 1, tau = 0.2, beta = 0.75, delta = 0.5)
standata <- list(y = dat$q,
                 resp = ifelse(dat$resp == "upper", 1, 0),
                 N = length(dat$resp))

and in the stan model, y ~ wiener(a, t, b, v) if the "upper" response was selected, and y ~ wiener(a, t, 1-b, -v) if the "lower" response was selected.

data {
  int<lower=0> N;
  real y[N];

  int<lower=0, upper=1> resp[N];

}
parameters {
  real<lower=0> a;
  real<lower=0> t;

  real<lower=0, upper=1> b;

  real v;
}
model {
  v ~ normal(0, 2);

  a ~ gamma(3, 3);
  t ~ gamma(4, 10);
  b ~ beta(5, 5);

  for (n in 1:N) {

      if (resp[n] == 1) {
          y[n] ~ wiener(a, t, b, v);
      }
      else {
          y[n] ~ wiener(a, t, 1-b, -v);
      }

  }
}

Full code example:

library(rstan)
library(RWiener)

set.seed(0)
dat <- rwiener(n = 5000, alpha = 1, tau = 0.2, beta = 0.75, delta = 0.5)

## stan model ----
wiener_model <- "

data {
    int<lower=0> N;
    real y[N];

    int<lower=0, upper=1> resp[N];

}
parameters {
    real<lower=0> a;
    real<lower=0> t;

    real<lower=0, upper=1> b;

    real v;
}
model {
    v ~ normal(0, 2);

    a ~ gamma(3, 3);
    t ~ gamma(4, 10);
    b ~ beta(5, 5);

    for (n in 1:N) {

        if (resp[n] == 1) {
            y[n] ~ wiener(a, t, b, v);
        }
        else {
            y[n] ~ wiener(a, t, 1-b, -v);
        }

    }
}"

## stan data ----
standata <- list(y = dat$q,
                 resp = ifelse(dat$resp == "upper", 1, 0),
                 N = length(dat$resp))

fit <- stan(model_code = wiener_model, data = standata)

